package main

import("encoding/json";"net/http";"strings";"github.com/jackc/pgx/v5/pgxpool")

func registerPOSDiscountApprovals(m *http.ServeMux,db *pgxpool.Pool){m.HandleFunc("GET /pos/discount-approvals",jsonAPI(authenticated(db,salesRoles...)(listPOSDiscountApprovals(db))));m.HandleFunc("POST /pos/discount-approvals",jsonAPI(authenticated(db,salesRoles...)(requestPOSDiscountApproval(db))));m.HandleFunc("POST /pos/discount-approvals/{id}/{action}",jsonAPI(authenticated(db,salesRoles...)(reviewPOSDiscountApproval(db))))}
func listPOSDiscountApprovals(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){c:=claimsFrom(r);rows,err:=db.Query(r.Context(),`SELECT a.id,u.name,a.gross,a.item_discount,a.invoice_discount,a.reason,a.status,COALESCE(a.review_note,''),a.created_at FROM pos_discount_approvals a JOIN users u ON u.id=a.requested_by WHERE a.tenant_id=$1 AND ($2='' OR a.status=$2) ORDER BY a.created_at DESC LIMIT 100`,c.Tenant,r.URL.Query().Get("status"));if err!=nil{http.Error(w,err.Error(),500);return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,user,reason,status,note string;var gross,item,invoice float64;var at any;if rows.Scan(&id,&user,&gross,&item,&invoice,&reason,&status,&note,&at)==nil{out=append(out,map[string]any{"id":id,"user":user,"gross":gross,"itemDiscount":item,"invoiceDiscount":invoice,"reason":reason,"status":status,"reviewNote":note,"createdAt":at})}};json.NewEncoder(w).Encode(out)}}
func requestPOSDiscountApproval(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x struct{Gross,ItemDiscount,InvoiceDiscount float64;Reason string};if json.NewDecoder(r.Body).Decode(&x)!=nil||x.Gross<=0||x.ItemDiscount<0||x.InvoiceDiscount<0||strings.TrimSpace(x.Reason)==""{http.Error(w,"sale value, discounts and reason are required",400);return};c:=claimsFrom(r);var id string;err:=db.QueryRow(r.Context(),`INSERT INTO pos_discount_approvals(tenant_id,requested_by,gross,item_discount,invoice_discount,reason)VALUES($1,$2,$3,$4,$5,$6)RETURNING id`,c.Tenant,c.Sub,x.Gross,x.ItemDiscount,x.InvoiceDiscount,strings.TrimSpace(x.Reason)).Scan(&id);if err!=nil{http.Error(w,err.Error(),409);return};auditUserAction(r,db,"POS_DISCOUNT_APPROVAL_REQUESTED",id,x);w.WriteHeader(201);json.NewEncoder(w).Encode(map[string]any{"id":id,"status":"pending"})}}
func reviewPOSDiscountApproval(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){c:=claimsFrom(r);if c.Role!="super_admin"&&c.Role!="admin"&&c.Role!="manager"{http.Error(w,"manager approval required",403);return};action:=r.PathValue("action");if action!="approve"&&action!="reject"{http.Error(w,"invalid action",404);return};var x struct{Note string `json:"note"`};json.NewDecoder(r.Body).Decode(&x);status:=map[string]string{"approve":"approved","reject":"rejected"}[action];tag,err:=db.Exec(r.Context(),`UPDATE pos_discount_approvals SET status=$3,reviewed_by=$4,reviewed_at=now(),review_note=NULLIF($5,'') WHERE id=$1 AND tenant_id=$2 AND status='pending'`,r.PathValue("id"),c.Tenant,status,c.Sub,strings.TrimSpace(x.Note));if err!=nil||tag.RowsAffected()!=1{http.Error(w,"pending approval not found",409);return};auditUserAction(r,db,"POS_DISCOUNT_"+strings.ToUpper(status),r.PathValue("id"),x);w.WriteHeader(204)}}
